    store_info_in_header("lang", "en-US", header);
    assert(header["Accept-Language"] == "en-US");

    // Test case 2: Valid 'encoding' type
    store_info_in_header("encoding", "gzip, deflate", header);
    assert(header["Accept-Encoding"] == "gzip, deflate");

    // Test case 3: Valid 'cache' type
