    assert(header["Cache-Control"] == "no-cache");

    // Test case 4: Invalid type - no changes expected
    std::map<std::string, std::string> original_header = header;
    store_info_in_header("invalid", "test", header);
    assert(header == original_header);

    return 0;
}

